export function criarCarrinho() {
  return { itens: [] };
}

export function adicionar(carrinho, produto, quantidade) {
  carrinho.itens.push({ produto, quantidade });
  return carrinho;
}

export function total(carrinho) {
  let soma = 0;
  for (const item of carrinho.itens) {
    soma = soma + item.produto.preco * item.quantidade;
  }
  return soma;
}

